def isBalanced(s: str) -> bool:
    balance_counter = 0
    for char in s:
        if char == '(':
            balance_counter += 1
        elif char == ')':
            balance_counter -= 1
        if balance_counter < 0:
            return False
    return balance_counter == 0

def main():
    test_strings = [
        "(())",
        "(()",
        "())()",
        "()(())"
    ]

    for s in test_strings:
        result = isBalanced(s)
        print(str(result).lower())

if __name__ == "__main__":
    main()

