import json
import os

def create_config_file(filename):
    config_data = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"]
    }
    with open(filename, 'w') as f:
        json.dump(config_data, f, indent=4)

def load_and_validate_config(filename):
    if not os.path.exists(filename):
        raise FileNotFoundError(f"Configuration file {filename} not found.")

    with open(filename, 'r') as f:
        try:
            config = json.load(f)
        except json.JSONDecodeError:
            raise ValueError("Failed to parse JSON content.")

    app_name = config.get("app_name")
    version = config.get("version")
    port = config.get("port")
    features = config.get("features")

    # Validate Port: between 1024 and 65535
    if not isinstance(port, int) or not (1024 <= port <= 65535):
        raise ValueError("Port must be an integer between 1024 and 65535.")

    # Validate Version: contains exactly two dots (X.Y.Z format)
    if not isinstance(version, str) or version.count('.') != 2:
        raise ValueError("Version must be in X.Y.Z format (exactly two dots).")

    # Validate Features: list is not empty
    if not isinstance(features, list) or len(features) == 0:
        raise ValueError("Features list must be a non-empty list.")

    # Print the result in the exact format required
    print(f"Loaded {app_name} v{version} on port {port} with {len(features)} features")

def main():
    config_filename = "app_config.json"

    # Ensure the file exists for the demonstration
    create_config_file(config_filename)

    try:
        load_and_validate_config(config_filename)
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

