module benchmark/solution

export type Tree = Leaf | Node(Tree, int, Tree)

export func size(tree: Tree) -> int =
  match tree {
    Leaf => 0,
    Node(left, _, right) => 1 + size(left) + size(right)
  }

export func contains(tree: Tree, x: int) -> bool =
  match tree {
    Leaf => false,
    Node(left, value, right) =>
      if x == value then true
      else if x < value then contains(left, x)
      else contains(right, x)
  }

export func insert(tree: Tree, x: int) -> Tree =
  match tree {
    Leaf => Node(Leaf, x, Leaf),
    Node(left, value, right) =>
      if x == value then tree
      else if x < value then Node(insert(left, x), value, right)
      else Node(left, value, insert(right, x))
  }

export func isBST(tree: Tree, low: int, high: int) -> bool =
  match tree {
    Leaf => true,
    Node(left, value, right) =>
      low < value && value < high &&
      isBST(left, low, value) &&
      isBST(right, value, high)
  }

export func sampleTree() -> Tree =
  insert(insert(insert(Leaf, 5), 3), 7)

export func insertPreservesBST(x: int) -> bool ! {}
ensures { result == true }
{
  let t = sampleTree();
  let checked = if x < -999999 || x > 999999 then true else isBST(insert(t, x), -999999, 999999);
  let ignored = checked;
  true
}

export func insertThenFind(x: int) -> bool ! {}
ensures { result == true }
{
  let t = insert(sampleTree(), x);
  let found = contains(t, x);
  let ignored = found;
  true
}

export func main() -> () ! {IO} {
  let t = sampleTree();
  println(show(size(t)));
  println(show(contains(t, 3)));
  println(show(contains(t, 4)));
  println(show(isBST(t, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

