module benchmark/solution
import std/string (chars, stringToInt)
import std/option (Option, Some, None)

pure func isDigit(c: string) -> bool =
  c == "0" || c == "1" || c == "2" || c == "3" || c == "4" || c == "5" || c == "6" || c == "7" || c == "8" || c == "9"

pure func consumeRun(ch: string, xs: [string], count: int) -> (int, [string]) =
  match xs {
    [] => (count, []),
    x :: rest => if x == ch then consumeRun(ch, rest, count + 1) else (count, x :: rest)
  }

pure func encodeChars(xs: [string]) -> string =
  match xs {
    [] => "",
    x :: rest => match consumeRun(x, rest, 1) {
      (count, remaining) => show(count) ++ x ++ encodeChars(remaining)
    }
  }

pure func encode(s: string) -> string =
  encodeChars(chars(s))

pure func spanDigits(xs: [string], acc: string) -> (string, [string]) =
  match xs {
    [] => (acc, []),
    x :: rest => if isDigit(x) then spanDigits(rest, acc ++ x) else (acc, x :: rest)
  }

pure func repeatChar(ch: string, n: int) -> string =
  if n <= 0 then "" else ch ++ repeatChar(ch, n - 1)

pure func decodeChars(xs: [string]) -> string =
  match xs {
    [] => "",
    _ => match spanDigits(xs, "") {
      (digits, rest) => match rest {
        [] => "",
        c :: rest2 => match stringToInt(digits) {
          Some(n) => repeatChar(c, n) ++ decodeChars(rest2),
          None => ""
        }
      }
    }
  }

pure func decode(s: string) -> string =
  decodeChars(chars(s))

pure func roundtrip(s: string) -> bool =
  decode(encode(s)) == s

pure func singleCharEncode(c: string) -> string =
  encode(c)

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(singleCharEncode("q"))
}

