def encode(s):
    if not s:
        return ""
    result = []
    i = 0
    while i < len(s):
        count = 1
        char = s[i]
        while i + 1 < len(s) and s[i + 1] == char:
            count += 1
            i += 1
        result.append(f"{count}{char}")
        i += 1
    return "".join(result)

def decode(s):
    if not s:
        return ""
    result = []
    i = 0
    while i < len(s):
        count_str = ""
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1
        count = int(count_str)
        char = s[i]
        result.append(char * count)
        i += 1
    return "".join(result)

def roundtrip(s):
    return decode(encode(s)) == s

def singleCharEncode(s):
    return encode(s)

if __name__ == "__main__":
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(roundtrip("hello"))
    print(singleCharEncode("q"))

