import std/io (println)
import std/fs (readFile, writeFile)
import std/string (split, trim, contains, stringToInt)
import std/json (Json, encode, jo, ja, kv, js, jnum)
import std/math (intToFloat)
import std/option (Option, Some, None)

type User = {name: string, age: int, email: string}

pure func validHeaders(headers: [string]) -> bool =
  match headers {
    h1 :: h2 :: h3 :: [] =>
      trim(h1) == "name" && trim(h2) == "age" && trim(h3) == "email",
    _ => false
  }

pure func makeUser(fields: [string]) -> Option[User] =
  match fields {
    name :: ageStr :: email :: [] => {
      let cleanName = trim(name);
      let cleanEmail = trim(email);
      match stringToInt(trim(ageStr)) {
        Some(age) => if age > 0 && contains(cleanEmail, "@") then Some({name: cleanName, age: age, email: cleanEmail}) else None,
        None => None
      }
    },
    _ => None
  }

pure func parseUser(headers: [string], fields: [string]) -> Option[User] =
  if validHeaders(headers) then makeUser(fields) else None

pure func parseRows(headers: [string], rows: [string]) -> [User] =
  match rows {
    [] => [],
    row :: rest =>
      if trim(row) == "" then parseRows(headers, rest)
      else {
        let fields = split(row, ",");
        match parseUser(headers, fields) {
          Some(user) => user :: parseRows(headers, rest),
          None => parseRows(headers, rest)
        }
      }
  }

pure func userToJson(user: User) -> Json =
  jo([
    kv("name", js(user.name)),
    kv("age", jnum(intToFloat(user.age))),
    kv("email", js(user.email))
  ])

pure func usersToJsons(users: [User]) -> [Json] =
  match users {
    [] => [],
    user :: rest => userToJson(user) :: usersToJsons(rest)
  }

pure func countUsers(users: [User]) -> int =
  match users {
    [] => 0,
    _ :: rest => 1 + countUsers(rest)
  }

export func main() -> () ! {IO, FS} {
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com";
  writeFile("users.csv", csvContent);
  let content = readFile("users.csv");
  let lines = split(content, "\n");
  let users = match lines {
    [] => [],
    headerLine :: dataLines => {
      let headers = split(headerLine, ",");
      parseRows(headers, dataLines)
    }
  };
  let jsonText = encode(ja(usersToJsons(users)));
  writeFile("users.json", jsonText);
  println("Converted " ++ show(countUsers(users)) ++ " valid rows to users.json")
}

