import typing

T = typing.TypeVar('T')
U = typing.TypeVar('U')

class Result(typing.Generic[T]):
    def bind(self, func: typing.Callable[[T], 'Result[U]']) -> 'Result[U]':
        if isinstance(self, Ok):
            return func(self.value)
        return self

class Ok(Result[T]):
    def __init__(self, value: T):
        self.value = value

class Err(Result[T]):
    def __init__(self, message: str):
        self.message = message

def validate_age(age: int) -> Result[int]:
    if 0 <= age <= 150:
        return Ok(age)
    return Err("Age out of range")

def calculate_retirement_years(age: int) -> Result[int]:
    if age < 65:
        return Ok(65 - age)
    return Err("Already retired")

def process_and_display(age: int) -> None:
    # Operations chained using the bind method
    result = validate_age(age).bind(calculate_retirement_years)

    if isinstance(result, Ok):
        print(f"Years to retirement: {result.value}")
    elif isinstance(result, Err):
        print(f"Error: {result.message}")

if __name__ == "__main__":
    test_cases = [30, 70, -5]
    for age in test_cases:
        process_and_display(age)

