pure func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

pure func enqueue(x: int, queue: [int]) -> [int] =
  match queue {
    [] => [x],
    y :: rest => y :: enqueue(x, rest)
  }

pure func enqueueMany(xs: [int], queue: [int]) -> [int] =
  match xs {
    [] => queue,
    x :: rest => enqueueMany(rest, enqueue(x, queue))
  }

pure func lookupNeighbors(graph: [(int, [int])], node: int) -> [int] =
  match graph {
    [] => [],
    entry :: rest =>
      match entry {
        (n, neighbors) => if n == node then neighbors else lookupNeighbors(rest, node)
      }
  }

pure func bfsLoop(graph: [(int, [int])], queue: [int], visited: [int], order: [int]) -> [int] =
  match queue {
    [] => order,
    node :: rest =>
      if contains(node, visited) then bfsLoop(graph, rest, visited, order)
      else {
        let neighbors = lookupNeighbors(graph, node);
        let nextQueue = enqueueMany(neighbors, rest);
        let nextVisited = enqueue(node, visited);
        let nextOrder = enqueue(node, order);
        bfsLoop(graph, nextQueue, nextVisited, nextOrder)
      }
  }

pure func bfs(graph: [(int, [int])], start: int) -> [int] =
