type Stats = {total: int, info: int, error: int, warning: int, users: [string]}

pure func logContent() -> string =
  "2024-10-29 10:00:00 INFO User logged in: alice" ++ "\n" ++
  "2024-10-29 10:01:15 ERROR Database connection failed" ++ "\n" ++
  "2024-10-29 10:02:30 INFO User logged in: bob" ++ "\n" ++
  "2024-10-29 10:03:45 WARNING High memory usage: 85%" ++ "\n" ++
  "2024-10-29 10:05:00 ERROR API timeout: /users endpoint" ++ "\n" ++
  "2024-10-29 10:06:15 INFO User logged out: alice"

pure func emptyStats() -> Stats =
  {total: 0, info: 0, error: 0, warning: 0, users: []}

pure func levelFromTokens(tokens: [string]) -> string =
  match tokens {
    _ :: _ :: level :: _ => level,
    _ => ""
  }

pure func messageFromTokens(tokens: [string]) -> string =
  join(" ", drop(3, tokens))

pure func containsUser(users: [string], user: string) -> bool =
  match users {
    [] => false,
    x :: rest => if x == user then true else containsUser(rest, user)
  }

pure func addUnique(users: [string], user: string) -> [string] =
  if containsUser(users, user) then users else user :: users

pure func userFromMessage(msg: string) -> Option[string] =
  if startsWith(msg, "User logged in: ") || startsWith(msg, "User logged out: ")
  then match split(msg, ": ") {
    _ :: name :: _ => Some(trim(name)),
    _ => None
  }
  else None

pure func updateLevel(stats: Stats, level: string) -> Stats =
  if level == "INFO" then {stats | info: stats.info + 1}
  else if level == "ERROR" then {stats | error: stats.error + 1}
  else if level == "WARNING" then {stats | warning: stats.warning + 1}
  else stats

pure func processLines(lines: [string], stats: Stats) -> Stats =
  match lines {
    [] => stats,
    line :: rest => {
      let tokens = split(line, " ");
      let level = levelFromTokens(tokens);
      let message = messageFromTokens(tokens);
      let s1 = {stats | total: stats.total + 1};
      let s2 = updateLevel(s1, level);
      let s3 = match userFromMessage(message) {
        Some(name) => {s2 | users: addUnique(s2.users, name)},
        None => s2
      };
      processLines(rest, s3)
    }
  }

pure func cmpString(a: string, b: string) -> int =
  if a < b then -1 else if a > b then 1 else 0

pure func pct(count: int, total: int) -> int =
  if total == 0 then 0 else (count * 100) / total

export func main() -> () ! {IO, FS} {
  let content = logContent();
  writeFile("app.log", content);
  let loaded = readFile("app.log");
  let stats = processLines(split(loaded, "\n"), emptyStats());
  let infoPct = pct(stats.info, stats.total);
  let errorPct = pct(stats.error, stats.total);
  let warningPct = 100 - infoPct - errorPct;
  let users = sortBy(cmpString, stats.users);
  println("Total log entries: " ++ show(stats.total));
  println("INFO: " ++ show(stats.info) ++ " (" ++ show(infoPct) ++ "%)");
  println("ERROR: " ++ show(stats.error) ++ " (" ++ show(errorPct) ++ "%)");
  println("WARNING: " ++ show(stats.warning) ++ " (" ++ show(warningPct) ++ "%)");
  println("Unique users: " ++ join(", ", users))
}

