        self.left = left
        self.right = right

class Let:
    def __init__(self, name, expr, body):
        self.name = name
        self.expr = expr
        self.body = body

def lookup(name, env):
    for n, v in reversed(env):
        if n == name:
            return v
    raise ValueError(f"Variable {name} not found")

def eval(expr, env):
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Var):
        return lookup(expr.name, env)
    elif isinstance(expr, Add):
        return eval(expr.left, env) + eval(expr.right, env)
    elif isinstance(expr, Mul):
        return eval(expr.left, env) * eval(expr.right, env)
    elif isinstance(expr, Let):
        val = eval(expr.expr, env)
        new_env = env + [(expr.name, val)]
        return eval(expr.body, new_env)
    else:
        raise TypeError("Unknown expression type")

