type Tree = Leaf(int) | Node(Tree, int, Tree)

pure func tree_sum(tree: Tree) -> int =
  match tree {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }

pure func find_max(tree: Tree) -> int =
  match tree {
    Leaf(v) => v,
    Node(l, v, r) =>
      match (l, r) {
        (Leaf(lv), Leaf(rv)) =>
          if v >= lv && v >= rv then v
          else if lv >= rv then lv
          else rv,
        (Leaf(lv), Node(_, _, _)) => {
          let rm = find_max(r);
          if v >= lv && v >= rm then v
          else if lv >= rm then lv
          else rm
        },
        (Node(_, _, _), Leaf(rv)) => {
          let lm = find_max(l);
          if v >= lm && v >= rv then v
          else if lm >= rv then lm
          else rv
        },
        (Node(_, _, _), Node(_, _, _)) => {
          let lm = find_max(l);
          let rm = find_max(r);
          if v >= lm && v >= rm then v
          else if lm >= rm then lm
          else rm
        }
      }
  }

export func main() -> () ! {IO} {
  let tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));
  let sum = tree_sum(tree);
  let maxv = find_max(tree);
