type State = Idle(int) | Moving(int, int) | DoorOpen(int, int)
type Event = Call(int) | Tick | Arrive

pure func transition(state: State, event: Event) -> State =
  match state {
    Idle(floor) => match event {
      Call(target) => if target == floor then DoorOpen(floor, 3) else Moving(floor, target),
      Tick => Idle(floor),
      Arrive => Idle(floor)
    },
    Moving(cur, target) => match event {
      Call(requested) => Moving(cur, target),
      Tick => Moving(cur, target),
      Arrive => DoorOpen(target, 3)
    },
    DoorOpen(floor, timer) => match event {
      Call(requested) => DoorOpen(floor, timer),
      Tick => if timer > 1 then DoorOpen(floor, timer - 1) else Idle(floor),
      Arrive => DoorOpen(floor, timer)
    }
  }

