pure func diff(expr: Expr, v: string) -> Expr =
  match expr {
    Const(_) => Const(0),
    Var(name) => if name == v then Const(1) else Const(0),
    Add(a, b) => Add(diff(a, v), diff(b, v)),
    Mul(a, b) => Add(Mul(a, diff(b, v)), Mul(b, diff(a, v)))
  }

pure func simplifyAdd(a: Expr, b: Expr) -> Expr =
  match (a, b) {
    (Const(0), e) => e,
    (e, Const(0)) => e,
    _ => Add(a, b)
  }

pure func simplifyMul(a: Expr, b: Expr) -> Expr =
  match (a, b) {
    (Const(0), _) => Const(0),
    (_, Const(0)) => Const(0),
    (Const(1), e) => e,
    (e, Const(1)) => e,
    _ => Mul(a, b)
  }

pure func simplify(expr: Expr) -> Expr =
  match expr {
    Const(n) => Const(n),
    Var(name) => Var(name),
    Add(a, b) => simplifyAdd(simplify(a), simplify(b)),
    Mul(a, b) => simplifyMul(simplify(a), simplify(b))
  }

pure func showExpr(expr: Expr) -> string =
  match expr {
    Const(n) => show(n),
    Var(name) => name,
    Add(a, b) => "(" ++ showExpr(a) ++ " + " ++ showExpr(b) ++ ")",
    Mul(a, b) => "(" ++ showExpr(a) ++ " * " ++ showExpr(b) ++ ")"
  }

export func main() -> () ! {IO} {
  let expr = Add(
    Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))),
    Const(5)
  );
  let derivative = diff(expr, "x");
  let simplified = simplify(derivative);
  println(showExpr(simplified))
}

