class Expr:
    pass

class Const(Expr):
    def __init__(self, val):
        self.val = val

class Var(Expr):
    def __init__(self, name):
        self.name = name

class Add(Expr):
    def __init__(self, left, right):
        self.left = left
        self.right = right

class Mul(Expr):
    def __init__(self, left, right):
        self.left = left
        self.right = right

def diff(expr, var):
    if isinstance(expr, Const):
        return Const(0)
    elif isinstance(expr, Var):
        return Const(1) if expr.name == var else Const(0)
    elif isinstance(expr, Add):
        return Add(diff(expr.left, var), diff(expr.right, var))
    elif isinstance(expr, Mul):
        return Add(
            Mul(expr.left, diff(expr.right, var)),
            Mul(expr.right, diff(expr.left, var))
        )
    return Const(0)

def simplify(expr):
    if isinstance(expr, Add):
        l = simplify(expr.left)
        r = simplify(expr.right)
        if isinstance(l, Const) and l.val == 0:
            return r
        if isinstance(r, Const) and r.val == 0:
            return l
        return Add(l, r)
    elif isinstance(expr, Mul):
        l = simplify(expr.left)
        r = simplify(expr.right)
        if (isinstance(l, Const) and l.val == 0) or (isinstance(r, Const) and r.val == 0):
            return Const(0)
        if isinstance(l, Const) and l.val == 1:
            return r
        if isinstance(r, Const) and r.val == 1:
            return l
        return Mul(l, r)
    return expr

def showExpr(expr):
    if isinstance(expr, Const):
        return str(expr.val)
    elif isinstance(expr, Var):
        return expr.name
    elif isinstance(expr, Add):
        return "(" + showExpr(expr.left) + " + " + showExpr(expr.right) + ")"
    elif isinstance(expr, Mul):
        return "(" + showExpr(expr.left) + " * " + showExpr(expr.right) + ")"
    return ""

if __name__ == "__main__":
    # x^2 + 3x + 5
    # Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))
    expr = Add(
        Add(
            Mul(Var("x"), Var("x")),
            Mul(Const(3), Var("x"))
        ),
        Const(5)
    )

    derivative = diff(expr, "x")
    simplified = simplify(derivative)
    print(showExpr(simplified))

