class Tree:
    pass

class Leaf(Tree):
    def __init__(self, value):
        self.value = value

class Node(Tree):
    def __init__(self, left, value, right):
        self.left = left
        self.value = value
        self.right = right

def mapTree(fn, tree):
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    elif isinstance(tree, Node):
        return Node(
            mapTree(fn, tree.left),
            fn(tree.value),
            mapTree(fn, tree.right)
        )

def foldTree(fn, acc, tree):
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    elif isinstance(tree, Node):
        acc = foldTree(fn, acc, tree.left)
        acc = fn(acc, tree.value)
        acc = foldTree(fn, acc, tree.right)
        return acc

def treeToList(tree):
    if isinstance(tree, Leaf):
        return [tree.value]
    elif isinstance(tree, Node):
        return treeToList(tree.left) + [tree.value] + treeToList(tree.right)
    return []

def treeDepth(tree):
    if isinstance(tree, Leaf):
        return 1
    elif isinstance(tree, Node):
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))
    return 0

# Helper functions for the test cases
double = lambda x: x * 2
add = lambda x, y: x + y

# Define the tree structure:
#       4
#      / \
#     2   6
#    / \ / \
#   1  3 5  7
tree = Node(
    Node(Leaf(1), 2, Leaf(3)),
    4,
    Node(Leaf(5), 6, Leaf(7))
)

# Printing results
print(treeToList(tree))
print(treeToList(mapTree(double, tree)))
print(foldTree(add, 0, tree))
print(treeDepth(tree))

