module benchmark/solution

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

pure func showType(t: Type) -> string =
  match t {
    TVar(name) => name,
    TInt => "TInt",
    TBool => "TBool",
    TFunc(arg, res) => "TFunc(" ++ showType(arg) ++ ", " ++ showType(res) ++ ")"
  }

pure func applyOne(varName: string, replacement: Type, t: Type) -> Type =
  match t {
    TVar(name) => if name == varName then replacement else TVar(name),
    TInt => TInt,
    TBool => TBool,
    TFunc(arg, res) => TFunc(applyOne(varName, replacement, arg), applyOne(varName, replacement, res))
  }

pure func apply(subst: [(string, Type)], t: Type) -> Type =
  match subst {
    [] => t,
    (varName, replacement) :: rest => apply(rest, applyOne(varName, replacement, t))
  }

type UnifyResult = UnifyOk([(string, Type)]) | UnifyFail(string)

pure func combineSubst(s1: [(string, Type)], s2: [(string, Type)]) -> [(string, Type)] =
  match s2 {
    [] => s1,
    (varName, t) :: rest => (varName, apply(s1, t)) :: combineSubst(s1, rest)
  }

pure func unify(t1: Type, t2: Type) -> UnifyResult =
  match t1 {
    TInt => match t2 {
      TInt => UnifyOk([]),
      TVar(name) => UnifyOk([(name, TInt)]),
      _ => UnifyFail("Cannot unify TInt with " ++ showType(t2))
    },
    TBool => match t2 {
      TBool => UnifyOk([]),
      TVar(name) => UnifyOk([(name, TBool)]),
      _ => UnifyFail("Cannot unify TBool with " ++ showType(t2))
    },
    TVar(name) => UnifyOk([(name, t2)]),
    TFunc(arg1, res1) => match t2 {
      TVar(name) => UnifyOk([(name, t1)]),
      TFunc(arg2, res2) => match unify(arg1, arg2) {
        UnifyFail(msg) => UnifyFail(msg),
        UnifyOk(s1) => match unify(apply(s1, res1), apply(s1, res2)) {
          UnifyFail(msg) => UnifyFail(msg),
          UnifyOk(s2) => UnifyOk(combineSubst(s1, s2))
        }
      },
      _ => UnifyFail("Cannot unify TFunc with " ++ showType(t2))
    }
  }

pure func findSubst(subst: [(string, Type)], varName: string) -> string =
  match subst {
    [] => "not found",
    (name, t) :: rest => if name == varName then showType(t) else findSubst(rest, varName)
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    UnifyFail(msg) => println("Unification failed: " ++ msg),
    UnifyOk(subst) => {
      println("a = " ++ findSubst(subst, "a"));
      println("b = " ++ findSubst(subst, "b"))
    }
  }
}

